                 } else if diff > state.filtered_pods.unwrap().len() {
                     (error_state(state), None)
                 } else {
                     let pod_name_or_none = state.filtered_pods.unwrap()[diff - 1].metadata.name;
                     if pod_name_or_none.is_none() {
